from decimal import Decimal
DANA = {"customer_key": 1, "customer_id": 1, "name": "Dana Whitfield", "email": "dana@example.com", "country": "CA", "monthly_fee": Decimal("49.00")}
SAM = {"customer_key": 3, "customer_id": 3, "name": "Sam Ortiz", "email": "sam@example.com", "country": "US", "monthly_fee": Decimal("99.00")}
DANA_NOW = {"customer_id": 1, "name": "Dana Whitfield", "email": "dana@whitfield.example", "country": "CA", "monthly_fee": Decimal("199.00")}
LEE = {"customer_id": 4, "name": "Lee Chen", "email": "lee@example.com", "country": "CA", "monthly_fee": Decimal("49.00")}
KIM = {"customer_id": 5, "name": "Kim Patel", "email": "kim@example.com", "country": "GB", "monthly_fee": Decimal("99.00")}
caller = [dict(DANA)]
apply_scd1(caller, [DANA_NOW])
assert apply_scd1([dict(DANA)], [DANA_NOW]) == [{"customer_key": 1, "customer_id": 1, "name": "Dana Whitfield", "email": "dana@whitfield.example", "country": "CA", "monthly_fee": Decimal("199.00")}], "a changed customer keeps one row under its old key, with the source's values"
assert caller == [DANA], "the dimension passed in is left as it was"
assert [row["customer_key"] for row in apply_scd1([dict(DANA), dict(SAM)], [LEE, KIM])] == [1, 3, 4, 5], "new customers get the next keys after the highest one, one each"
assert [row["customer_key"] for row in apply_scd1([], [LEE])] == [1], "an empty dimension starts its keys at 1"
